def minPath(grid, k):
    m = len(grid)
    n = len(grid[0])
    if k > m * n:
        return []
    if k == 0:
        return []
    res = [[-1 for i in range(n)] for j in range(m)]
    res[0][0] = grid[0][0]
    for i in range(1, m):
        res[i][0] = res[i - 1][0]
        for j in range(1, n):
            res[i][j] = res[i - 1][j]
            if j != 0:
                res[i][j] += res[i - 1][j - 1]
            else:
                res[i][j] += res[i - 1][j]
    for i in range(1, m):
        for j in range(1, n):
            res[i][j] = min(res[i - 1][j], 
                            res[i][j - 1]) + grid[i][j]
    return res[m - 1][n - 1]

